7	export type CreatePayslipResult =
8	  | { success: true; payslipId: string }
9	  | { success: false; error: string };
10	
11	export async function createPayslip(
12	  businessId: string,
13	  cashierId: string,
14	  periodStart: string,
15	  periodEnd: string,
16	): Promise<CreatePayslipResult> {
17	  if (!periodStart || !periodEnd || periodStart > periodEnd) {
18	    return { success: false, error: "Rentang tanggal tidak valid." };
19	  }
20	
21	  const supabase = await createClient();
22	
23	  const { data: cashier } = await supabase
24	    .from("cashiers")
25	    .select("name, daily_rate")
26	    .eq("id", cashierId)
27	    .eq("business_id", businessId)
28	    .maybeSingle();
29	
30	  if (!cashier) {
31	    return { success: false, error: "Kasir tidak ditemukan." };
32	  }
33	
34	  const { data: attendanceRows } = await supabase
35	    .from("attendance")
36	    .select("status")
37	    .eq("business_id", businessId)
38	    .eq("cashier_id", cashierId)
39	    .gte("date", periodStart)
40	    .lte("date", periodEnd);
41	
42	  const counts = { hadir: 0, izin: 0, sakit: 0, alpa: 0 };
43	  for (const r of attendanceRows ?? []) {
44	    counts[r.status as keyof typeof counts] += 1;
45	  }
46	
47	  const dailyRate = Number(cashier.daily_rate);
48	  const basePay = dailyRate * counts.hadir;
49	
50	  const { data: payslip, error } = await supabase
51	    .from("payslips")
52	    .insert({
53	      business_id: businessId,
54	      cashier_id: cashierId,
55	      period_start: periodStart,
56	      period_end: periodEnd,
57	      daily_rate: dailyRate,
58	      hadir_count: counts.hadir,
59	      izin_count: counts.izin,
60	      sakit_count: counts.sakit,
61	      alpa_count: counts.alpa,
62	      base_pay: basePay,
63	    })
64	    .select("id")
65	    .single();
66	
67	  if (error || !payslip) {
68	    return { success: false, error: error?.message ?? "Gagal membuat slip gaji." };
69	  }
70	
71	  await logActivity(
72	    supabase,
73	    businessId,
74	    "sistem",
75	    "sukses",
76	    `Slip gaji dibuat: ${cashier.name}`,
77	    `${periodStart} s/d ${periodEnd} · ${counts.hadir} hari kerja`,
78	  );
79	
80	  revalidatePath(`/business/${businessId}/payroll`);
81	  return { success: true, payslipId: payslip.id };
82	}
