92	export async function addPayslipAdjustment(
93	  businessId: string,
94	  payslipId: string,
95	  type: AdjustmentType,
96	  label: string,
97	  amount: number,
98	): Promise<{ error: string | null }> {
99	  const trimmedLabel = label.trim();
100	  if (!trimmedLabel) {
101	    return { error: "Nama tunjangan/potongan wajib diisi." };
102	  }
103	  if (Number.isNaN(amount) || amount <= 0) {
104	    return { error: "Nominal harus angka lebih dari 0." };
105	  }
106	
107	  const supabase = await createClient();
108	
109	  const { data: payslip } = await supabase
110	    .from("payslips")
111	    .select("id")
112	    .eq("id", payslipId)
113	    .eq("business_id", businessId)
114	    .maybeSingle();
115	
116	  if (!payslip) {
117	    return { error: "Slip gaji tidak ditemukan." };
118	  }
119	
120	  const { error } = await supabase.from("payslip_adjustments").insert({
121	    payslip_id: payslipId,
122	    type,
123	    label: trimmedLabel,
124	    amount,
125	  });
126	
127	  if (error) {
128	    return { error: error.message };
129	  }
130	
131	  await logActivity(
132	    supabase,
133	    businessId,
134	    "sistem",
135	    "info",
136	    `${type === "tunjangan" ? "Tunjangan" : "Potongan"} ditambahkan: ${trimmedLabel}`,
137	    `Rp${amount.toLocaleString("id-ID")}`,
138	  );
139	
140	  revalidatePath(`/business/${businessId}/payroll/${payslipId}`);
141	  return { error: null };
