8	type SupabaseServerClient = Awaited<ReturnType<typeof createClient>>;
9	
10	const PURCHASE_INGREDIENT_CATEGORY = "Pembelian Bahan Baku";
11	const PURCHASE_PRODUCT_CATEGORY = "Pembelian Barang Dagang";
12	
13	// Kategori pengeluaran non-pembelian → akun beban di Daftar Akun. Kategori di
14	// luar daftar ini (harusnya tidak terjadi karena dropdown form sudah dibatasi)
15	// jatuh ke "Beban Lain-lain".
16	const EXPENSE_CATEGORY_ACCOUNT: Record<string, string> = {
17	  Sewa: "5-102",
18	  "Gaji & Upah": "5-100",
19	  "Listrik & Air": "5-101",
20	  Marketing: "5-103",
21	  Perlengkapan: "5-104",
22	  "Lain-lain": "5-999",
23	};
24	
25	// Return value: pesan error kalau posting jurnal gagal, null kalau sukses.
26	// Baris expenses sudah kadung tersimpan di titik ini (lihat pemanggil) — jadi
27	// kegagalan di sini tidak dibatalkan, hanya dilaporkan supaya tidak diam-diam
28	// bikin buku besar tidak lengkap (lihat [[mini-erp-scope]]).
29	async function postExpenseJournal(
30	  supabase: SupabaseServerClient,
31	  businessId: string,
32	  date: string,
33	  category: string,
34	  amount: number,
35	  isPurchase: boolean,
36	): Promise<string | null> {
37	  const debitAccount = isPurchase ? "1-200" : EXPENSE_CATEGORY_ACCOUNT[category] ?? "5-999";
38	  const { error } = await supabase.rpc("post_journal_entry", {
39	    p_business_id: businessId,
40	    p_date: date,
41	    p_description: `Pengeluaran: ${category}`,
42	    p_lines: [
43	      { account_code: debitAccount, debit: amount, credit: 0 },
44	      { account_code: "1-001", debit: 0, credit: amount },
45	    ],
46	  });
47	  return error?.message ?? null;
48	}
