13	async function postPurchaseJournal(
14	  supabase: SupabaseServerClient,
15	  businessId: string,
16	  date: string,
17	  description: string,
18	  amount: number,
19	  paidAmount: number,
20	): Promise<string | null> {
21	  const lines: { account_code: string; debit: number; credit: number }[] = [
22	    { account_code: "1-200", debit: amount, credit: 0 },
23	  ];
