29	    lines.push({ account_code: "2-001", debit: 0, credit: sisaUtang });
30	  }
31	  const { error } = await supabase.rpc("post_journal_entry", {
32	    p_business_id: businessId,
33	    p_date: date,
34	    p_description: description,
35	    p_lines: lines,
36	  });
37	  return error?.message ?? null;
38	}
