53	  const qtyRaw = formData.get("qty") as string;
54	
55	  if (!date) {
56	    return { error: "Tanggal wajib diisi." };
57	  }
58	  if (category !== "Bahan Baku" && category !== "Barang Dagang") {
59	    return { error: "Kategori tidak valid." };
60	  }
61	
62	  const amount = Number(amountRaw);
63	  if (!amountRaw || Number.isNaN(amount) || amount <= 0) {
64	    return { error: "Total pembelian harus angka lebih dari 0." };
65	  }
66	
67	  const paidAmount = paidAmountRaw ? Number(paidAmountRaw) : 0;
68	  if (Number.isNaN(paidAmount) || paidAmount < 0) {
69	    return { error: "Jumlah dibayar harus angka dan tidak boleh negatif." };
70	  }
71	  if (paidAmount > amount) {
72	    return { error: "Jumlah dibayar tidak boleh lebih besar dari total pembelian." };
73	  }
74	
75	  const qty = Number(qtyRaw);
76	  if (!qtyRaw || Number.isNaN(qty) || qty <= 0) {
77	    return { error: "Qty dibeli harus angka lebih dari 0." };
78	  }
79	
