81	
82	  let ingredientId: string | null = null;
83	  let productId: string | null = null;
84	  let itemName = "";
85	
86	  if (category === "Bahan Baku") {
87	    ingredientId = formData.get("ingredientId") as string;
88	    if (!ingredientId) {
89	      return { error: "Pilih bahan yang dibeli." };
90	    }
91	
92	    const { data: ingredient } = await supabase
93	      .from("ingredients")
94	      .select("id, name, business_id, stock, unit_cost")
95	      .eq("id", ingredientId)
96	      .single();
97	
98	    if (!ingredient || ingredient.business_id !== businessId) {
99	      return { error: "Bahan baku tidak ditemukan." };
100	    }
101	    itemName = ingredient.name;
102	
103	    const oldValue = Number(ingredient.stock) * Number(ingredient.unit_cost);
104	    const newStock = Number(ingredient.stock) + qty;
105	    const newUnitCost =
106	      newStock > 0 ? Math.round((oldValue + amount) / newStock) : Number(ingredient.unit_cost);
107	
108	    const { error: updateError } = await supabase
109	      .from("ingredients")
110	      .update({ stock: newStock, unit_cost: newUnitCost })
111	      .eq("id", ingredientId);
112	
113	    if (updateError) {
114	      return { error: updateError.message };
115	    }
116	
117	    if (newUnitCost !== Number(ingredient.unit_cost)) {
118	      await supabase.from("ingredient_price_history").insert({
119	        business_id: businessId,
120	        ingredient_id: ingredientId,
121	        unit_cost: newUnitCost,
122	        source: "pembelian",
123	      });
124	      await recalculateProductCostsForIngredient(supabase, ingredientId);
125	    }
126	  } else {
127	    productId = formData.get("productId") as string;
128	    if (!productId) {
129	      return { error: "Pilih produk yang dibeli." };
130	    }
131	
132	    const { data: product } = await supabase
133	      .from("products")
134	      .select("id, name, business_id, stock, cost")
135	      .eq("id", productId)
136	      .single();
137	
